$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "  if\(G&&G\.bagOpen&&!G\.over\) return;\r?\n  var HOl=hudOff\('legend'\);"
$r1="  // v28.xx (cw-wheelnolegend), UI step 4 (critic on screen 61): the controls list sat on top of the item wheel and cut its labels. It steps aside while the wheel is open, as it does for the backpack.`n  if(G&&(G.bagOpen||G.wheel)&&!G.over) return;`n  var HOl=hudOff('legend');"
$chk=@'
  {v:'VER',what:'the controls list steps aside while the item wheel is open (it covered the wheel labels)',
   run:function(){
     if(typeof __frame!=='function') return 'SKIP: no frame helper';
     var PR=CanvasRenderingContext2D.prototype, of=PR.fillText, g=null, n=0;
     try{
       __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       g=__state(); if(!g||!g.player) return 'SKIP: no raid';
       g.legendOn=1; g.legendAutoDone=true;
       PR.fillText=function(s){ if(/wasd|ctrl/i.test(String(s))) n++; return of.apply(this,arguments); };
       __frame(); __frame();
       if(!n) return 'SKIP: the controls list was not drawn with no wheel open';
       n=0;
       g.wheel={t:0,list:[],sel:-1,mx:0,my:0,ox:0,oy:0,armed:0,d:0};
       __frame(); __frame();
       g.wheel=null;
       PR.fillText=of;
       if(n) return 'the controls list is still drawn ('+n+' texts) while the item wheel is open';
       return null;
     } finally {
       PR.fillText=of;
       try{ if(g) g.wheel=null; }catch(_w){}
       try{ __endRaid('abandon'); }catch(_e){}
       __topClear();
     } }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='NO CONTROLS LIST OVER THE WHEEL'
  why='UI step 4: the critic found the controls list drawn on top of the item wheel, cutting off its labels. It now steps aside while the wheel is open, the same way it does for the backpack.'
  now='The controls list hides while the item wheel is open.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-wheelnolegend.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
'written'
EOF
